-- Read-only postcheck; compare baseline row counts/legacy values to the verified backup.
-- Zero blockers plus metadata are necessary, not proof of MySQL/runtime/browser acceptance.
SELECT DATABASE() AS selected_schema,VERSION() AS server_version;
SELECT table_name,column_name,column_type,is_nullable,column_default,datetime_precision FROM information_schema.columns WHERE table_schema=DATABASE() AND (table_name LIKE 'alert_%' OR table_name='measurement_command') ORDER BY table_name,ordinal_position;
SELECT table_name,index_name,non_unique,seq_in_index,column_name,sub_part FROM information_schema.statistics WHERE table_schema=DATABASE() AND (table_name LIKE 'alert_%' OR table_name='measurement_command') ORDER BY table_name,index_name,seq_in_index;
SELECT table_name,constraint_name,column_name,referenced_table_name,referenced_column_name FROM information_schema.key_column_usage WHERE constraint_schema=DATABASE() AND referenced_table_name IS NOT NULL AND (table_name LIKE 'alert_%' OR table_name='measurement_command' OR table_name='care_plan_notification') ORDER BY table_name,constraint_name,ordinal_position;
SELECT trigger_name,event_object_table,event_manipulation,action_timing,SHA2(action_statement,256) AS body_sha256 FROM information_schema.triggers WHERE trigger_schema=DATABASE() AND trigger_name LIKE 'aw57\_%' ORDER BY trigger_name;
SELECT workflow_version,COUNT(*) AS alert_count FROM alert_record GROUP BY workflow_version;
SELECT 'reserved_marker_conflicts' AS check_name,COUNT(*) AS blockers FROM alert_record WHERE (alert_type='MEASUREMENT_FOLLOW_UP' AND workflow_version<>1) OR (workflow_version=1 AND (alert_type IS NULL OR alert_type<>'MEASUREMENT_FOLLOW_UP'));
SELECT 'orphan_alert_events' AS check_name,COUNT(*) AS blockers FROM alert_event e LEFT JOIN alert_record a ON a.id=e.alert_id WHERE (e.event_type IS NOT NULL AND (a.id IS NULL OR a.patient_id<>e.patient_id OR a.workflow_version<>1 OR a.alert_type IS NULL OR a.alert_type<>'MEASUREMENT_FOLLOW_UP')) OR ((a.workflow_version=1 OR a.alert_type='MEASUREMENT_FOLLOW_UP') AND (e.event_type IS NULL OR a.patient_id<>e.patient_id));
SELECT 'invalid_source_links' AS check_name,COUNT(*) AS blockers FROM alert_source_link l LEFT JOIN alert_source_identity s ON s.id=l.source_identity_id LEFT JOIN alert_record a ON a.id=l.alert_id WHERE s.id IS NULL OR a.id IS NULL OR s.source_type<>l.source_type OR s.source_id<>l.source_id OR a.patient_id<>s.patient_id OR a.workflow_version<>1 OR a.alert_type IS NULL OR a.alert_type<>'MEASUREMENT_FOLLOW_UP' OR a.source_type IS NULL OR a.source_type<>l.source_type OR a.source_id IS NULL OR a.source_id<>l.source_id OR a.metric_key IS NULL OR a.metric_key<>l.metric_key;
SELECT 'incomplete_alert_commands' AS check_name,COUNT(*) AS blockers FROM alert_command WHERE alert_id IS NULL OR result_json IS NULL;
SELECT 'incomplete_measurement_commands' AS check_name,COUNT(*) AS blockers FROM measurement_command WHERE source_id IS NULL OR result_json IS NULL;
SELECT 'invalid_delivery_jobs' AS check_name,COUNT(*) AS blockers FROM alert_notification n LEFT JOIN alert_event e ON e.id=n.event_id WHERE e.id IS NULL OR e.patient_id<>n.patient_id OR n.attempt_count NOT BETWEEN 0 AND 3;
SELECT 'invalid_source_revision_provenance' AS check_name,COUNT(*) AS blockers FROM alert_source_revision WHERE source_status NOT IN ('ACTIVE','INVALIDATED') OR (revision_no=1 AND source_status<>'ACTIVE') OR (revision_no>1 AND (correction_reason IS NULL OR CHAR_LENGTH(TRIM(correction_reason))=0)) OR CHAR_LENGTH(correction_reason)>1000;
SELECT 'source_revision_status_mismatch' AS check_name,COUNT(*) AS blockers FROM alert_source_identity s LEFT JOIN alert_source_revision r ON r.source_identity_id=s.id AND r.revision_no=s.current_revision WHERE r.id IS NULL OR r.source_status<>s.status;
-- Missing/invalid private qualification metadata blocks use; never backfill unknown history with '{}'.
SELECT 'unknown_source_action_qualification' AS check_name,COUNT(*) AS blockers FROM alert_source_revision WHERE action_versions_json IS NULL OR JSON_VALID(action_versions_json)=0 OR JSON_TYPE(CASE WHEN JSON_VALID(action_versions_json)=1 THEN action_versions_json ELSE 'null' END)<>'OBJECT' OR (revision_no=1 AND action_versions_json<>'{}');
